import type * as React from "react"


import { Logo } from "@/components/ui/logo"

/** Brand hero: the lockup (mark beside the brand name) large and centered on the band. */
export default function LogoHero({ name = "Clossys", mark }: { name?: string; mark?: React.ReactNode }) {
  return (
    <section data-slot="logo-hero" data-brand="named" className="py-16 md:py-24">
      <div className="mx-auto flex max-w-5xl justify-center px-6">
        <Logo content="lockup" size="lg" name={name} mark={mark} />
      </div>
    </section>
  )
}
